import 'dart:convert';
import 'dart:io';
import 'package:image/image.dart' as img;
void main(){const p='/private/tmp/dart3d-u3-outline-view-probe-20261028/r1/parent';final pairs=[['before/00-off.png','split/00-off.png'],['before/01-off-set.png','before/04-outline-set.png'],['before/00-off.png','split/05-clear-rendered.png'],['split/00-off.png','split/12-off-return.png']];final result=<Map<String,Object>>[];for(final pair in pairs){final a=img.decodePng(File('$p/${pair[0]}').readAsBytesSync())!,b=img.decodePng(File('$p/${pair[1]}').readAsBytesSync())!;var changed=0,maxDifference=0;for(var y=70;y<670;y++)for(var x=0;x<402;x++){final aa=a.getPixel(x,y),bb=b.getPixel(x,y);var d=0;for(var c=0;c<3;c++){final v=(aa[c]-bb[c]).abs().toInt();if(v>d)d=v;}if(d>0)changed++;if(d>maxDifference)maxDifference=d;}result.add({'left':pair[0],'right':pair[1],'crop':[0,70,402,600],'changedPixels':changed,'maxRGBDifference':maxDifference});}File('$p/pixel-comparisons.json').writeAsStringSync(const JsonEncoder.withIndent('  ').convert(result));print(jsonEncode(result));}
